"""Uzbekistan map geometry for the home-page SVG map.

Generated from Natural Earth borders (via the world-atlas package), projected
with an equirectangular projection centred on 41.3°N. Public domain data.
"""

import math

LON0, LAT1 = 55.6, 45.9
K = math.cos(math.radians(41.3))
SCALE = 73.94943146889352
WIDTH, HEIGHT = 1000, 666


def project(lat, lon):
    """Latitude/longitude to SVG x, y."""
    return round((lon - LON0) * K * SCALE, 1), round((LAT1 - lat) * SCALE, 1)


